import type { FieldDef } from "@/lib/engine/types";
import type { Category } from "./types";

const t = (key: string, label: string, placeholder?: string): FieldDef => ({ key, label, type: "text", placeholder, maxLen: 300 });
const ta = (key: string, label: string, placeholder?: string): FieldDef => ({ key, label, type: "textarea", placeholder, maxLen: 6000 });
const sel = (key: string, label: string, options: string[]): FieldDef => ({ key, label, type: "select", options: ["", ...options] });

const NICHE = t("niche", "Niche / topic", "e.g. home workouts for busy parents");
const HANDLE_STATS = t("current", "Where you are now", "e.g. 1,200 followers, 2 posts/week");
const LEVEL = sel("level", "Current level", ["complete beginner", "beginner", "intermediate", "advanced"]);
const TIME = t("time", "Time available", "e.g. 1 hour a day for 6 weeks");
const BUDGET = t("budget", "Budget", "e.g. ₹20,000 or $300");
const REGION = t("region", "Location / market", "e.g. India, tier-2 cities");
const SOURCE = ta("source", "Paste the text / data", "Paste the content the AI should work from");

